css:
.fx-dslant .sec{position:relative;flex:1;display:grid;align-content:center;justify-items:center;text-align:center;gap:.8em;padding:5em 1.25em}
.fx-dslant .sec h2{font-size:clamp(1.8em,4vw,2.8em);max-width:16em}.fx-dslant .sec p{opacity:.75;max-width:44ch}
.fx-dslant .sec .k{font-size:.75em;font-weight:700;letter-spacing:.16em;text-transform:uppercase;opacity:.7}
.fx-dslant{--sl:clamp(36px,7vw,110px);display:flex;flex-direction:column;background:var(--surface)}
.fx-dslant .s1{background:var(--surface);padding-bottom:calc(var(--sl) + 4em)}
.fx-dslant .s2{z-index:2;margin-top:calc(var(--sl)*-1);padding:calc(var(--sl) + 4em) 1.25em calc(var(--sl) + 4em);background:linear-gradient(135deg,var(--primary),color-mix(in srgb,var(--primary) 70%,var(--accent)));color:var(--on-primary);clip-path:polygon(0 var(--sl),100% 0,100% calc(100% - var(--sl)),0 100%)}
.fx-dslant .s3{z-index:1;margin-top:calc(var(--sl)*-1);padding-top:calc(var(--sl) + 4em);background:color-mix(in srgb,var(--accent) 14%,var(--surface))}
@media(prefers-reduced-motion:reduce){.fx-dslant .sec{transition:none}}
